<script setup lang="ts">
import {computed} from 'vue';import {useRoute,useRouter} from 'vue-router';import {phases,slides} from '../content/learning';import {useProgress} from '../composables/useProgress';import UiIcon from './UiIcon.vue';
const {done,storageOK,percent,reset,toggle}=useProgress();const route=useRoute(),router=useRouter();const index=computed(()=>Number(route.params.index)||0);const isSlide=computed(()=>route.name==='slide');const phase=computed(()=>isSlide.value?slides[index.value]?.phase: index.value);
function confirmReset(){if(confirm('清除這個瀏覽器中的學習進度？'))reset();}
</script>
<template><footer><div class="learning-controls"><nav class="chapter-track" aria-label="階段導覽"><RouterLink v-for="p in phases" :key="p.id" :to="`/slide/${p.slide}`" :class="{current:p.id===phase}"><span class="track-dot"></span><b>{{String(p.id+1).padStart(2,'0')}}</b><small>{{p.title}}</small></RouterLink></nav><div v-if="isSlide" class="slide-controls"><button class="previous" aria-label="上一頁" :disabled="index===0" @click="router.push(`/slide/${index-1}`)"><UiIcon name="left" :size="18"/></button><span>{{String(index+1).padStart(2,'0')}} <span class="slash">/</span> 16</span><button data-complete :aria-pressed="done.includes(index)" :class="{completed:done.includes(index)}" @click="toggle(index)"><UiIcon :name="done.includes(index)?'check':'bookmark'" :size="19"/>{{done.includes(index)?'已完成':'標記完成'}}</button><RouterLink v-if="index===15" class="primary" to="/map/8">回到地圖<UiIcon name="right" :size="18"/></RouterLink><button v-else class="primary" @click="router.push(`/slide/${index+1}`)">下一頁<UiIcon name="right" :size="18"/></button></div></div><div class="progress-row"><span id="progress"><b>{{percent}}%</b><progress max="16" :value="done.length" aria-label="學習進度"/>{{done.length}} / 16 頁已完成 <small>{{storageOK?'僅儲存在此瀏覽器':'本次進度無法持久儲存'}}</small></span><span class="hint">← → 切換簡報 · Esc 返回地圖</span><button @click="confirmReset">重設進度</button></div></footer></template>
